import{_ as n,a0 as g,w as p,s as i,I as r,x as s,a1 as t,A as l,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const O=JSON.parse('{"title":"CentOS上配置rsyslog客户端用以遠程記錄日誌 | LCTT x X-CMD","titleTemplate":false,"description":"CentOS上配置rsyslog客户端用以遠程記錄日誌 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CentOS上配置rsyslog客户端用以遠程記錄日誌 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CentOS上配置rsyslog客户端用以遠程記錄日誌 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20141210 How to configure rsyslog client for remote logging on CentOS","title":"CentOS上配置rsyslog客户端用以遠程記錄日誌","tag":"201502","desc":""},"relativePath":"201502/20141210 How to configure rsyslog client for remote logging on CentOS.md","filePath":"[post].md"}'),y={name:"201502/20141210 How to configure rsyslog client for remote logging on CentOS.md"};function d(u,o,m,f,C,S){const e=g("Link");return p(),i("div",null,[o[19]||(o[19]=r("h1",{id:"centos上配置rsyslog客户端用以遠程記錄日誌",tabindex:"-1"},[s("CentOS上配置rsyslog客户端用以遠程記錄日誌 "),r("a",{class:"header-anchor",href:"#centos上配置rsyslog客户端用以遠程記錄日誌","aria-label":"Permalink to “CentOS上配置rsyslog客户端用以遠程記錄日誌”"},"​")],-1)),o[20]||(o[20]=r("p",null,[r("strong",null,"rsyslog"),s("是一個開源工具，被廣泛用於Linux系統以通過TCP/UDP協議轉發或接收日誌消息。rsyslog守護進程可以被配置成兩種環境，一種是配置成日誌收集服務器，rsyslog進程可以從網絡中收集其它主機上的日誌數據，這些主機會將日誌配置為發送到另外的遠程服務器。rsyslog的另外一個用法，就是可以配置為客户端，用來過濾和發送內部日誌消息到本地文件夾（如/var/log）或一台可以路由到的遠程rsyslog服務器上。")],-1)),r("p",null,[o[1]||(o[1]=s("假定你的網絡中已經有一台",-1)),t(e,{href:"http://xmodulo.com/configure-syslog-server-linux.html"},{default:l(()=>[...o[0]||(o[0]=[s("已經配置好並啓動的",-1)])]),_:1}),o[2]||(o[2]=s("rsyslog服務器，本指南將為你展示如何來設置CentOS系統將其內部日誌消息路由到一台遠程rsyslog服務器上。這將大大改善你的系統磁盤空間的使用，尤其是當你還沒有一個用於/var目錄的獨立的大分區。",-1))]),o[21]||(o[21]=a(`<h3 id="步驟一-安裝rsyslog守護進程" tabindex="-1">步驟一： 安裝Rsyslog守護進程 <a class="header-anchor" href="#步驟一-安裝rsyslog守護進程" aria-label="Permalink to “步驟一： 安裝Rsyslog守護進程”">​</a></h3><p>在CentOS 6和7上，rsyslog守護進程已經預先安裝了。要驗證rsyslog是否已經安裝到你的CentOS系統上，請執行如下命令：</p><pre><code># rpm -qa | grep rsyslog
# rsyslogd -v 
</code></pre><p><img src="https://farm8.staticflickr.com/7502/15988316295_ac2e07e7f3_z.jpg" alt=""></p><p>如果處於某種原因，rsyslog守護進程沒有出現在你的系統中，請使用以下命令來安裝：</p><pre><code> # yum install rsyslog 
</code></pre><h3 id="步驟二-配置rsyslog守護進程為客户端" tabindex="-1">步驟二： 配置Rsyslog守護進程為客户端 <a class="header-anchor" href="#步驟二-配置rsyslog守護進程為客户端" aria-label="Permalink to “步驟二： 配置Rsyslog守護進程為客户端”">​</a></h3><p>接下來的步驟，是要將你的CentOS機器轉變成rsyslog客户端，將其所有內部日誌消息發送到遠程中央日誌服務器上。</p><p>要實現該功能，請使用你喜愛的文本編輯器打開位於/etc路徑下的rsyslog主配置文件：</p><pre><code># nano /etc/rsyslog.conf 
</code></pre><p>開啓文件用於編輯後，你需要添加以下聲明到文件底部。將IP地址替換為你的遠程rsyslog服務器的IP地址。</p><pre><code>*.*  @192.168.1.25:514 
</code></pre><p>上面的聲明告訴rsyslog守護進程，將系統上各個設備的各種日誌消息路由到遠程rsyslog服務器（192.168.1.25）的UDP端口514。</p><p>如果出於某種原因，你需要更為可靠的協議，如TCP，而rsyslog服務器也被配置為監聽TCP連接，你必須在遠程主機的IP地址前添加一個額外的@字符，像下面這樣：</p><pre><code>*.*  @@192.168.1.25:514 
</code></pre><p>注意，你也可以將rsyslog服務器的IP地址替換成它的主機名（FQDN）。</p><p>如果你只想要轉發服務器上的指定設備的日誌消息，比如説內核設備，那麼你可以在rsyslog配置文件中使用以下聲明。</p><pre><code>kern.* @192.168.1.25:514 
</code></pre><p>修改配置文件後，你需要重啓進程以激活修改：</p><p><strong>CentOS 7：</strong></p><pre><code># systemctl restart rsyslog.service 
</code></pre><p><strong>CentOS 6：</strong></p><pre><code> # service rsyslog restart 
</code></pre><p>####非 syslog 日誌的轉發</p><p>在另外一種環境中，讓我們假定你已經在機器上安裝了一個名為“foobar”的應用程序，它會在/var/log下生成foobar.log日誌文件。現在，你想要將它的日誌定向到rsyslog服務器，這可以通過像下面這樣在rsyslog配置文件中加載imfile模組來實現。</p><p>首先，加載imfile模組，這隻需做一次。</p><pre><code>module(load=&quot;imfile&quot; PollingInterval=&quot;5&quot;) 
</code></pre><p>然後，指定日誌文件的路徑以便imfile模組可以檢測到：</p><pre><code>input(type=&quot;imfile&quot;
      File=&quot;/var/log/foobar.log&quot;
      Tag=&quot;foobar&quot;
      Severity=&quot;error&quot;
      Facility=&quot;local7&quot;)
</code></pre><p>最後，定向local7設備到遠程rsyslog服務器：</p><pre><code>local7.* @192.168.1.25:514
</code></pre><p>別忘了重啓rsyslog進程哦！</p><h3 id="步驟三-讓rsyslog進程自動啓動" tabindex="-1">步驟三： 讓Rsyslog進程自動啓動 <a class="header-anchor" href="#步驟三-讓rsyslog進程自動啓動" aria-label="Permalink to “步驟三： 讓Rsyslog進程自動啓動”">​</a></h3><p>要讓rsyslog客户端在每次系統重啓後自動啓動，請運行以下命令：</p><p><strong>CentOS 7：</strong></p><pre><code># systemctl enable rsyslog.service 
</code></pre><p><strong>CentOS 6：</strong></p><pre><code># chkconfig rsyslog on 
</code></pre><h3 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to “小結”">​</a></h3>`,39)),r("p",null,[o[4]||(o[4]=s("在本教程中，我演示瞭如何將CentOS系統轉變成rsyslog客户端以強制它發送日誌消息到遠程rsyslog服務器。這裏我假定rsyslog客户端和服務器之間的連接是安全的（如，在有防火牆保護的公司網絡中）。不管在任何情況下，都不要配置rsyslog客户端將日誌消息通過不安全的網絡轉發，或者，特別是通過互聯網轉發，因為syslog協議是一個明文協議。要進行安全傳輸，可以考慮使用",-1)),t(e,{href:"http://www.rsyslog.com/doc/rsyslog_tls.html"},{default:l(()=>[...o[3]||(o[3]=[s("TLS/SSL",-1)])]),_:1}),o[5]||(o[5]=s("來加密日誌消息的傳輸。",-1))]),o[22]||(o[22]=r("hr",null,null,-1)),r("p",null,[o[7]||(o[7]=s("via: ",-1)),t(e,{href:"http://xmodulo.com/configure-rsyslog-client-centos.html"},{default:l(()=>[...o[6]||(o[6]=[s("http://xmodulo.com/configure-rsyslog-client-centos.html",-1)])]),_:1})]),r("p",null,[o[11]||(o[11]=s("作者：",-1)),t(e,{href:"http://xmodulo.com/author/caezsar"},{default:l(()=>[...o[8]||(o[8]=[s("Caezsar M",-1)])]),_:1}),o[12]||(o[12]=s(" 譯者：",-1)),t(e,{href:"https://github.com/GOLinux"},{default:l(()=>[...o[9]||(o[9]=[s("GOLinux",-1)])]),_:1}),o[13]||(o[13]=s(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:l(()=>[...o[10]||(o[10]=[s("wxy",-1)])]),_:1})]),r("p",null,[o[16]||(o[16]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[14]||(o[14]=[s("LCTT",-1)])]),_:1}),o[17]||(o[17]=s(" 原創翻譯，",-1)),t(e,{href:"http://linux.cn/"},{default:l(()=>[...o[15]||(o[15]=[s("Linux中國",-1)])]),_:1}),o[18]||(o[18]=s(" 榮譽推出",-1))])])}const P=n(y,[["render",d]]);export{O as __pageData,P as default};
